import{_ as r,C as d,o as l,c as n,a2 as o,j as i,a,E as s}from"./chunks/framework.Dx-TCpNt.js";const q=JSON.parse('{"title":"常见问题与故障排查","description":"缺页、语言目录无法识别、切格不准、导出缺图、原图找不到、桌面端数据目录错误等常见问题的排查方法。","frontmatter":{"description":"缺页、语言目录无法识别、切格不准、导出缺图、原图找不到、桌面端数据目录错误等常见问题的排查方法。"},"headers":[],"relativePath":"zh/faq.md","filePath":"zh/faq.md","lastUpdated":1794768712000}'),c={name:"zh/faq.md"};function h(p,e,g,u,m,b){const t=d("Badge");return l(),n("div",null,[e[2]||(e[2]=o('<h1 id="常见问题与故障排查" tabindex="-1">常见问题与故障排查 <a class="header-anchor" href="#常见问题与故障排查" aria-label="Permalink to &quot;常见问题与故障排查&quot;">​</a></h1><p>出问题了。这一页从症状倒推原因——不用靠猜。</p><h2 id="图库是空的" tabindex="-1">图库是空的 <a class="header-anchor" href="#图库是空的" aria-label="Permalink to &quot;图库是空的&quot;">​</a></h2><p><strong>现象：</strong> 侧边栏提示没有找到任何卷。</p><p>检查 <code>raw/</code> 下的文件夹结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/&lt;volume&gt;/&lt;language-dir&gt;/&lt;chapter&gt;/001.jpg</span></span></code></pre></div><p>常见原因：</p><ul><li>卷文件夹存在，但语言文件夹未被识别。使用卷设置进行映射，或把它重命名为 <code>ja</code>、<code>zh</code> 或 <code>en</code>（别名列在<a href="/KomaYomi-docs/zh/guide/gallery">图库</a>中）。</li><li>话文件夹直接位于卷之下（<code>raw/&lt;volume&gt;/001.jpg</code>）。必须有一层语言目录。</li><li>桌面应用的数据目录指向了别处。按 <code>Ctrl+Shift+D</code> 选择正确的文件夹，或设置 <code>MANGA_DATA_DIR</code>。</li></ul><h2 id="某一页缺少某种语言" tabindex="-1">某一页缺少某种语言 <a class="header-anchor" href="#某一页缺少某种语言" aria-label="Permalink to &quot;某一页缺少某种语言&quot;">​</a></h2><p><strong>现象：</strong> 某页只显示 <code>JA</code> 和 <code>ZH</code>；<code>EN</code> 被禁用。</p><p>页面按排序后的索引配对。如果该话中的英文文件少一个，最后一页就没有英文图片。页面警告会指出缺失的语言和页码。补上该文件或删掉多余的页面。</p><p>如果数量一致但配对错误，请检查文件名：开头的数字与排序位置不一致会触发警告。重命名文件，让自然排序符合预期顺序。</p><h2 id="文件名看起来没问题-但页面顺序乱了" tabindex="-1">文件名看起来没问题，但页面顺序乱了 <a class="header-anchor" href="#文件名看起来没问题-但页面顺序乱了" aria-label="Permalink to &quot;文件名看起来没问题，但页面顺序乱了&quot;">​</a></h2><p>排序是<strong>自然排序</strong>：连续数字按数值比较，因此 <code>2.jpg</code> 排在 <code>10.jpg</code> 之前。它不是按字节的字典序。如果文件没有开头数字，它可能会排在带数字的文件之前。请统一加上页码前缀，例如 <code>001.jpg</code>、<code>002.jpg</code>。</p><h2 id="分格检测不准确" tabindex="-1">分格检测不准确 <a class="header-anchor" href="#分格检测不准确" aria-label="Permalink to &quot;分格检测不准确&quot;">​</a></h2><ul><li><strong>左右两侧的竖条被忽略了。</strong> 这是有意为之：窄的边缘竖条（通常是 <em>あらすじ</em> 或作者注）会被过滤，以免成为误判的分格。合法的边缘分格请手动绘制。</li><li><strong>跨页大图</strong> 常常产生一个大分格加上若干碎片。选中碎片并<strong>合并</strong>。</li><li><strong>非常小或非常细的框</strong> 会作为噪声被过滤。如果它们是真实分格，请手动添加。</li><li><strong>WebP 页面不会被解码</strong> 用于检测。如果需要自动检测，请转换为 JPEG/PNG。</li><li><strong>固定的杂志版式</strong> 更适合用<a href="/KomaYomi-docs/zh/extending">布局模板</a>，而不是检测。</li></ul><p>修正分格之后，除非你愿意丢失手动绘制的框，否则不要重新运行自动检测。</p><h2 id="导出的-html-里没有图片" tabindex="-1">导出的 HTML 里没有图片 <a class="header-anchor" href="#导出的-html-里没有图片" aria-label="Permalink to &quot;导出的 HTML 里没有图片&quot;">​</a></h2><p><strong>文件夹模式（默认）：</strong> HTML 引用同级的 <code>&lt;name&gt;.files/</code> 目录。请把 <code>.html</code> 文件<strong>和</strong> <code>.files</code> 文件夹一起复制，并保持它们的相对位置。只打开 HTML，或把它移出该文件夹，都会导致图片失效。</p><p><strong>单文件模式：</strong> 图片已内嵌，因此只需要 HTML 文件。代价是体积——整话可能达到几十兆字节。</p><h2 id="找不到原始图片" tabindex="-1">找不到原始图片 <a class="header-anchor" href="#找不到原始图片" aria-label="Permalink to &quot;找不到原始图片&quot;">​</a></h2><p><strong>现象：</strong> <code>.mnproj</code> 导入报告图片缺失，或某页显示 404 占位图。</p><ul><li><strong>引用模式的项目</strong> 存储的是路径，而不是图片。如果图片被移动，请重新导入并设置<strong>重新关联目录</strong>。导入器先按 SHA-1 匹配，再按文件名匹配，并优先选择包含卷名和话名的文件夹。</li><li><strong>打包模式的项目</strong> 把图片放在 <code>assets/</code> 中。缺少资源意味着项目包不完整；请重新导出。</li><li>如果图片仍然存在但被重命名了，请把它们放入符合预期结构的文件夹，然后使用重新关联。</li></ul><h2 id="我的编辑丢失了" tabindex="-1">我的编辑丢失了 <a class="header-anchor" href="#我的编辑丢失了" aria-label="Permalink to &quot;我的编辑丢失了&quot;">​</a></h2><p>检查工具栏中的保存模式：</p><ul><li><strong>自动</strong> 会以防抖方式保存。</li><li><strong>确认</strong> 需要点击保存勾选。带着未保存的改动离开会显示浏览器警告，但崩溃或强制关闭仍可能丢失最后的编辑。</li></ul><p>同时确认你打开的是同一页：URL hash 包含卷、话、页码和视图。在另一个数据目录上打开应用会显示不同的图库。</p><h2 id="应用模板后分格笔记消失了" tabindex="-1">应用模板后分格笔记消失了 <a class="header-anchor" href="#应用模板后分格笔记消失了" aria-label="Permalink to &quot;应用模板后分格笔记消失了&quot;">​</a></h2><p>当分格模板（或重新检测）改变了分格数量时，分格级笔记无法被可靠映射，因此会被丢弃。页面级笔记始终保留。如果数量不变，笔记会按阅读顺序重新映射。</p><p>为避免这种情况，在把模板应用到整话之前先导出一个备份。</p><h2 id="端口-5173-已被占用" tabindex="-1">端口 5173 已被占用 <a class="header-anchor" href="#端口-5173-已被占用" aria-label="Permalink to &quot;端口 5173 已被占用&quot;">​</a></h2><p>Vite 配置为 <code>strictPort: false</code>，因此它会转移到下一个空闲端口。请查看终端输出中的实际 URL。文档站点使用 <code>5174</code>。</p><h2 id="如何备份所有内容" tabindex="-1">如何备份所有内容？ <a class="header-anchor" href="#如何备份所有内容" aria-label="Permalink to &quot;如何备份所有内容？&quot;">​</a></h2><ul><li><strong>备份 ZIP</strong> —— 整个 <code>data/</code>（JSON、模板、预设），不包括缩略图缓存。</li><li><strong><code>.mnproj</code></strong> —— 项目包，可含图片也可不含图片。</li><li><strong>复制文件夹</strong> —— <code>raw/</code> 是你的图片；<code>data/</code> 是你的工作成果；<code>exports/</code> 可以重新生成。</li></ul><p>参见<a href="/KomaYomi-docs/zh/remote-backup">远程存储与备份</a>。</p><h2 id="遇到错误码怎么办" tabindex="-1">遇到错误码怎么办？ <a class="header-anchor" href="#遇到错误码怎么办" aria-label="Permalink to &quot;遇到错误码怎么办？&quot;">​</a></h2><p>服务端与 CLI 会返回 <code>ERR_*</code> / <code>WARN_*</code> / <code>STATUS_*</code> 稳定错误码，而 <code>error</code> / <code>message</code> 文本会按请求语言本地化。完整错误码与 HTTP 契约见<a href="/KomaYomi-docs/server/error-codes">服务端与 CLI 消息码</a>（英文页面，以英文为准）。</p><h2 id="缩略图看起来过期或损坏" tabindex="-1">缩略图看起来过期或损坏 <a class="header-anchor" href="#缩略图看起来过期或损坏" aria-label="Permalink to &quot;缩略图看起来过期或损坏&quot;">​</a></h2><p>删除 <code>data/cache/thumbs/</code>。它是缓存，会按需重建。备份和项目包本来就不包含它。</p><h2 id="搜索笔记没有结果" tabindex="-1">搜索笔记没有结果 <a class="header-anchor" href="#搜索笔记没有结果" aria-label="Permalink to &quot;搜索笔记没有结果&quot;">​</a></h2><ul><li>搜索覆盖笔记正文、标签和来源。请检查当前生效的卷/话/标签/来源筛选。</li><li>笔记必须被<strong>保存</strong>后才会被索引。在确认模式下，未保存的编辑还不在磁盘上。</li><li>总览会索引页面 JSON；保存失败的页面没有可搜索的笔记。</li></ul><h2 id="桌面应用启动了-但显示的是旧页面集" tabindex="-1">桌面应用启动了，但显示的是旧页面集 <a class="header-anchor" href="#桌面应用启动了-但显示的是旧页面集" aria-label="Permalink to &quot;桌面应用启动了，但显示的是旧页面集&quot;">​</a></h2><p>桌面窗口可能使用了与仓库不同的数据目录。检查窗口标题（其中包含数据路径），然后按 <code>Ctrl+Shift+D</code> 切换。<code>MANGA_DATA_DIR</code> 会覆盖已保存的设置。</p><h2 id="怎么导出-pdf-或-word" tabindex="-1">怎么导出 PDF 或 Word？ <a class="header-anchor" href="#怎么导出-pdf-或-word" aria-label="Permalink to &quot;怎么导出 PDF 或 Word？&quot;">​</a></h2><p>按 <code>E</code>，在导出对话框里选择 <strong>PDF（打印）</strong> 或 <strong>Word 文档</strong>。</p><ul><li><strong>PDF（打印）</strong> 会打开打印页并唤起浏览器打印对话框，在里面选 <strong>另存为 PDF</strong>。</li><li><strong>Word 文档</strong> 会下载一个 <code>.docx</code>，里面包含页面图片，以及转成可编辑文本的整页/格级笔记。标注暂不写入 <code>.docx</code>。</li></ul>',46)),i("p",null,[e[0]||(e[0]=a("词表导出仍为",-1)),s(t,{type:"warning",text:"计划中"}),e[1]||(e[1]=a("。",-1))]),e[3]||(e[3]=o('<h2 id="怎样创建分格分组" tabindex="-1">怎样创建分格分组？ <a class="header-anchor" href="#怎样创建分格分组" aria-label="Permalink to &quot;怎样创建分格分组？&quot;">​</a></h2><p>在切格工作台选中一个或多个分格，点击<strong>成组</strong>。新分组会出现在<strong>分组</strong>面板里，可以改名、换颜色、拖动标签调整顺序、并入上一组、拆分或删除（删除分组不会删掉分格）。<strong>按组排序</strong>会按分组顺序重新编号整页。分组会随页面交换文件、工程包和导出一起保留；见<a href="/KomaYomi-docs/zh/guide/panels#分组">切格工作台</a>。矢量<strong>标注</strong>也已实现：箭头、矩形、椭圆、高亮、自由画笔、文本、徽标和马赛克。</p><h2 id="它会把我的数据发送到任何地方吗" tabindex="-1">它会把我的数据发送到任何地方吗？ <a class="header-anchor" href="#它会把我的数据发送到任何地方吗" aria-label="Permalink to &quot;它会把我的数据发送到任何地方吗？&quot;">​</a></h2><p>默认不会。服务器监听 <code>127.0.0.1</code>，不配置远端目标时不会上传任何内容。有两类操作会发起外部请求：笔记来源中可选的“获取页面标题”（请求你输入的 URL，超时 5 秒），以及你主动添加的 WebDAV / 网络存储目标（按需拉取图片、上传备份）。未配置存储目标时，所有数据都留在本机。</p><h2 id="旧的页面-json-打不开" tabindex="-1">旧的页面 JSON 打不开 <a class="header-anchor" href="#旧的页面-json-打不开" aria-label="Permalink to &quot;旧的页面 JSON 打不开&quot;">​</a></h2><p>手改过的或较旧的 JSON 在读取时会被规范化：缺失的 id 会被生成，矩形会被限制范围，无效的枚举值会回退到默认值，悬空的分组引用会被移除。如果文件根本不是有效的 JSON，应用会认为该页没有数据并重新检测——这会在保存时覆盖该文件。如果发生这种情况，请从备份恢复。</p><h2 id="还有其他问题" tabindex="-1">还有其他问题 <a class="header-anchor" href="#还有其他问题" aria-label="Permalink to &quot;还有其他问题&quot;">​</a></h2><p>求助之前先收集下面这些——未来的你会感谢现在的你：</p><ol><li>启动 <code>npm run dev</code> 或 <code>npm run desktop</code> 的终端输出。</li><li>确切的页面路径（<code>data/pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</code>）。</li><li>删除 <code>data/cache/thumbs/</code> 后问题是否仍然复现。</li><li>如果问题与检测相关，提供 <code>node scripts/manga-cli.ts report</code> 的输出。</li></ol>',9))])}const P=r(c,[["render",h]]);export{q as __pageData,P as default};
